def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # For repeated horizontal bands of one foreground color, extend every
    # shorter band to the right edge of the longest one, marking added cells 1.
    bands = []
    for r, row in enumerate(grid):
        cells = [c for c, v in enumerate(row) if v != background]
        if cells and cells == list(range(cells[0], cells[-1] + 1)):
            color = row[cells[0]]
            if all(row[c] == color for c in cells):
                bands.append((r, cells[0], cells[-1], color))
    if len(bands) >= 2 and len({b[3] for b in bands}) == 1 and len({b[1] for b in bands}) == 1:
        target = max(b[2] for b in bands)
        for r, left, right, color in bands:
            for c in range(right + 1, target + 1):
                out[r][c] = 1
        return out

    # Otherwise, if repeated row patterns have a longer continuation, copy
    # that continuation into the shorter matching row using color 1.
    for r, row in enumerate(grid):
        marks = [c for c, v in enumerate(row) if v != background]
        if not marks:
            continue
        end = max(marks)
        for other_r, other in enumerate(grid):
            if other_r == r:
                continue
            if any(row[c] != other[c] for c in range(end + 1)):
                continue
            for c in range(end + 1, w):
                if other[c] != background and row[c] == background:
                    out[r][c] = 1
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
